package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.zip.Zip64ExtendedInformationExtraField;
import org.apache.commons.compress.archivers.zip.ZipException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.springframework.test.util.ReflectionTestUtils;
import static org.junit.Assert.*;

public class Zip64ExtendedInformationExtraField_reparseCentralDirectoryData_TriageGen0Test {

    private static final int DWORD = 8;
    private static final int WORD = 2;

    /**
     * Helper to inject rawCentralDirectoryData into the private field using reflection
     */
    private void setRawData(Zip64ExtendedInformationExtraField field, byte[] data) {
        ReflectionTestUtils.setField(field, "rawCentralDirectoryData", data);
    }

    @Test
    public void testReparse_NullRawData() throws ZipException {
        Zip64ExtendedInformationExtraField extraField = new Zip64ExtendedInformationExtraField();
        setRawData(extraField, null);

        // Should return without doing anything or throwing exception
        extraField.reparseCentralDirectoryData(true, true, true, true);
        Assert.assertNull(extraField.getSize());
    }

    @Test
    public void testReparse_AllTrue_Success() throws ZipException {
        Zip64ExtendedInformationExtraField extraField = new Zip64ExtendedInformationExtraField();
        // expectedLength = 8 + 8 + 8 + 2 = 26
        byte[] data = new byte[26];
        for (int i = 0; i < data.length; i++) {
            data[i] = (byte) i;
        }
        setRawData(extraField, data);

        extraField.reparseCentralDirectoryData(true, true, true, true);

        Assert.assertNotNull(extraField.getSize());
        Assert.assertNotNull(extraField.getCompressedSize());
        Assert.assertNotNull(extraField.getRelativeHeaderOffset());
        Assert.assertNotNull(extraField.getDiskStartNumber());
    }

    @Test
    public void testReparse_AllFalse_Success() throws ZipException {
        Zip64ExtendedInformationExtraField extraField = new Zip64ExtendedInformationExtraField();
        // expectedLength = 0
        byte[] data = new byte[0];
        setRawData(extraField, data);

        extraField.reparseCentralDirectoryData(false, false, false, false);

        Assert.assertNull(extraField.getSize());
        Assert.assertNull(extraField.getCompressedSize());
        Assert.assertNull(extraField.getRelativeHeaderOffset());
        Assert.assertNull(extraField.getDiskStartNumber());
    }

    @Test
    public void testReparse_PartialTrue_Success() throws ZipException {
        Zip64ExtendedInformationExtraField extraField = new Zip64ExtendedInformationExtraField();
        // hasUncompressedSize (8) + hasDiskStart (2) = 10
        byte[] data = new byte[10];
        setRawData(extraField, data);

        extraField.reparseCentralDirectoryData(true, false, false, true);

        Assert.assertNotNull(extraField.getSize());
        Assert.assertNull(extraField.getCompressedSize());
        Assert.assertNull(extraField.getRelativeHeaderOffset());
        Assert.assertNotNull(extraField.getDiskStartNumber());
    }

    @Test(expected = ZipException.class)
    public void testReparse_LengthMismatch_ThrowsException() throws ZipException {
        Zip64ExtendedInformationExtraField extraField = new Zip64ExtendedInformationExtraField();
        // Expected 8 (for uncompressed size), but providing 5
        byte[] data = new byte[5];
        setRawData(extraField, data);

        extraField.reparseCentralDirectoryData(true, false, false, false);
    }

    @Test
    public void testReparse_SpecificCombinations() throws ZipException {
        Zip64ExtendedInformationExtraField extraField = new Zip64ExtendedInformationExtraField();

        // Case: only CompressedSize and RelativeHeaderOffset (8 + 8 = 16)
        byte[] data = new byte[16];
        setRawData(extraField, data);
        extraField.reparseCentralDirectoryData(false, true, true, false);
        Assert.assertNull(extraField.getSize());
        Assert.assertNotNull(extraField.getCompressedSize());
        Assert.assertNotNull(extraField.getRelativeHeaderOffset());
        Assert.assertNull(extraField.getDiskStartNumber());

        // Case: only DiskStart (2)
        byte[] data2 = new byte[2];
        setRawData(extraField, data2);
        extraField.reparseCentralDirectoryData(false, false, false, true);
        Assert.assertNull(extraField.getSize());
        Assert.assertNull(extraField.getCompressedSize());
        Assert.assertNull(extraField.getRelativeHeaderOffset());
        Assert.assertNotNull(extraField.getDiskStartNumber());
    }
}
